import{_ as e,c as a,o as s,a2 as t}from"./chunks/framework.B3iQLowF.js";const n=JSON.parse('{"title":"Demo: BrandPulse in Action","description":"","frontmatter":{},"headers":[],"relativePath":"docs/brandpulse/demo.md","filePath":"docs/brandpulse/demo.md","lastUpdated":1741550455000}');const i=e({name:"docs/brandpulse/demo.md"},[["render",function(e,n,i,o,r,l){return s(),a("div",null,n[0]||(n[0]=[t('<h1 id="demo-brandpulse-in-action" tabindex="-1">Demo: BrandPulse in Action <a class="header-anchor" href="#demo-brandpulse-in-action" aria-label="Permalink to &quot;Demo: BrandPulse in Action&quot;">​</a></h1><p>BrandPulse is my battle-tested data pipeline, built to simulate, process, and visualize tweet storms at breakneck speed. This demo puts it center stage: millions of tweets surging through Kafka, sentiment sliced and diced, and a dashboard glowing with real-time insights. I’ve pushed it hard, and it delivers—here’s what it looks like when the rubber meets the road.</p><hr><h2 id="what-you-re-about-to-see" tabindex="-1">What You’re About to See <a class="header-anchor" href="#what-you-re-about-to-see" aria-label="Permalink to &quot;What You’re About to See&quot;">​</a></h2><p>I designed BrandPulse to tackle a deluge of fake tweets—peaking at a theoretical 32,000,000 per second—with sentiment analysis baked in, all processed and stored at scale. The demo shows:</p><ul><li><strong>Tweet Generation</strong>: <code>producer.js</code> pumps out 8,000-tweet batches every millisecond across 4 workers into Kafka’s &quot;tweets&quot; topic.</li><li><strong>Ingestion &amp; Processing</strong>: <code>consumer.js</code> pulls those tweets, aggregates sentiment counts, and feeds them to InfluxDB.</li><li><strong>Visualization</strong>: My dashboard tracks it live, plotting sentiment trends per second with no lag.</li></ul><p>This is the real deal—optimized, battle-hardened, and ready to impress.</p><hr><h2 id="setting-up-the-demo" tabindex="-1">Setting Up the Demo <a class="header-anchor" href="#setting-up-the-demo" aria-label="Permalink to &quot;Setting Up the Demo&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ol><li><p><strong>Kafka Topic</strong>: I set up the &quot;tweets&quot; topic with 32 partitions for max throughput:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/kafka-topics.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replication-factor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --partitions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tweets</span></span></code></pre></div><p>The 32 partitions let Kafka spread the load, keeping my 4 workers busy.</p></li><li><p><strong>Start the Stack</strong>: Kafka, InfluxDB, and my Node.js scripts need to be running. Check my repo for Docker setups.</p></li><li><p><strong>Launch Producer</strong>: <code>node src/producer.js</code> fires up the tweet storm.</p></li><li><p><strong>Run Consumer</strong>: <code>node src/consumer.js</code> grabs, processes, and stores the data.</p></li><li><p><strong>Open Dashboard</strong>: Hit the InfluxDB UI or my custom dashboard (linked in the repo).</p></li></ol><h3 id="the-action" tabindex="-1">The Action <a class="header-anchor" href="#the-action" aria-label="Permalink to &quot;The Action&quot;">​</a></h3><ul><li><strong>Generation</strong>: I aim for 50M tweets. Batches of 8,000 hit Kafka every 1ms—insane speed, real results.</li><li><strong>Ingestion</strong>: The consumer aggregates sentiment (e.g., 20k positive/sec) and flushes to InfluxDB every 5s or 5k points.</li><li><strong>Display</strong>: The dashboard updates live, graphing sentiment swings as they happen.</li></ul><hr><h2 id="demo-output-metrics-in-motion" tabindex="-1">Demo Output: Metrics in Motion <a class="header-anchor" href="#demo-output-metrics-in-motion" aria-label="Permalink to &quot;Demo Output: Metrics in Motion&quot;">​</a></h2><p>I’ve tracked BrandPulse with <code>monitor.js</code>, and it’s a sight to behold. Here are some real runs:</p><h3 id="run-1-34-complete" tabindex="-1">Run 1: 34% Complete <a class="header-anchor" href="#run-1-34-complete" aria-label="Permalink to &quot;Run 1: 34% Complete&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BrandPulse Tweet Generation Metrics</span></span>\n<span class="line"><span>[▓▓▓▓▓▓▓▓▓▓░░░░░░░░░░░░░░░░░░░░] 34.32%</span></span>\n<span class="line"><span>├─ Total Tweets: 17,160,000 / 50,000,000</span></span>\n<span class="line"><span>├─ Throughput (current): 707,200 tweets/sec</span></span>\n<span class="line"><span>├─ Throughput (avg): 571,886 tweets/sec</span></span>\n<span class="line"><span>├─ Elapsed: 00:00:30</span></span>\n<span class="line"><span>├─ Remaining: 00:00:57</span></span>\n<span class="line"><span>└─ Errors: 0</span></span></code></pre></div><ul><li><strong>What’s Happening</strong>: Half a minute in, I’m cranking out 700k+ tweets/sec—way past my initial 60k/sec mark.</li></ul><h3 id="run-2-18-complete" tabindex="-1">Run 2: 18% Complete <a class="header-anchor" href="#run-2-18-complete" aria-label="Permalink to &quot;Run 2: 18% Complete&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BrandPulse Tweet Generation Metrics</span></span>\n<span class="line"><span>[▓▓▓▓▓▓░░░░░░░░░░░░░░░░░░░░░░░░] 18.82%</span></span>\n<span class="line"><span>├─ Total Tweets: 9,408,000 / 50,000,000</span></span>\n<span class="line"><span>├─ Throughput (current): 710,400 tweets/sec</span></span>\n<span class="line"><span>├─ Throughput (avg): 587,523 tweets/sec</span></span>\n<span class="line"><span>├─ Elapsed: 00:00:16</span></span>\n<span class="line"><span>├─ Remaining: 00:01:09</span></span>\n<span class="line"><span>└─ Errors: 0</span></span></code></pre></div><ul><li><strong>What’s Happening</strong>: Early in the run, I’m already hitting 710k/sec—proof my 32-partition Kafka setup and worker tweaks paid off.</li></ul><p>These numbers show BrandPulse flexing its muscles—stable, fast, and error-free.</p><hr><h2 id="dashboard-snapshots" tabindex="-1">Dashboard Snapshots <a class="header-anchor" href="#dashboard-snapshots" aria-label="Permalink to &quot;Dashboard Snapshots&quot;">​</a></h2><p>Here’s what the dashboard looks like, pulling live data from InfluxDB. These screenshots live in my <code>/assets/</code> folder:</p><h3 id="fixed-mode-steady-sentiment" tabindex="-1">Fixed Mode: Steady Sentiment <a class="header-anchor" href="#fixed-mode-steady-sentiment" aria-label="Permalink to &quot;Fixed Mode: Steady Sentiment&quot;">​</a></h3><p><img src="/assets/dashboard-1.JmqNDJe7.png" alt="Fixed Mode Dashboard"></p><ul><li><strong>Details</strong>: 35% positive, 30% negative, 35% neutral—rock-solid distribution, just as I set it.</li></ul><h3 id="volatile-mode-wild-swings" tabindex="-1">Volatile Mode: Wild Swings <a class="header-anchor" href="#volatile-mode-wild-swings" aria-label="Permalink to &quot;Volatile Mode: Wild Swings&quot;">​</a></h3><p><img src="/assets/dashboard-2.BR4diGM1.png" alt="Volatile Mode Dashboard"></p><ul><li><strong>Details</strong>: Sentiment bouncing from 50% netural to 10% in seconds—my <code>volatilityFactor</code> at 0.8 doing its thing.</li></ul><p>These visuals bring the metrics to life—smooth lines for fixed mode, jagged chaos for volatile.</p><hr><h3 id="performance-under-the-hood" tabindex="-1">Performance Under the Hood <a class="header-anchor" href="#performance-under-the-hood" aria-label="Permalink to &quot;Performance Under the Hood&quot;">​</a></h3><p>To see how this holds up at 700K+ tweets/sec, I ran some CPU profiling while the consumer was chugging along. Check out the snapshot below—it’s a look at how the system balances Kafka reads, aggregation, and InfluxDB writes across my 8-core machine:</p><p><img src="/assets/cpu-profile.C9x-1J_x.png" alt="CPU Profile of InfluxDB Integration"><br><em>CPU usage during a 700K+ tweets/sec run—aggregation keeps writes light, but Kafka reads chew some cycles. Don’t try this with the dashboard open unless you enjoy rebooting!</em></p><p>The profile shows the load split: Kafka ingestion hogs the CPU like a kid with a bag of candy (those big batches aren’t free), while aggregation and writes sip resources thanks to the 3-points-per-second trick. It’s proof the setup scales without turning my machine into a toaster—well, almost. If you dare run the data generation, ingestion, <em>and</em> dashboard all at once, good luck! My system hung more times than I can count—think “frozen like a deer in headlights” vibes. I had to dial back the worker count and shrink the buffer size from “RAM-gobbling monster” to “plays nice with others” just to keep it breathing.</p><p>So just minimize the workers and buffer size for testing!</p><h2 id="demo-modes-two-flavors-of-awesome" tabindex="-1">Demo Modes: Two Flavors of Awesome <a class="header-anchor" href="#demo-modes-two-flavors-of-awesome" aria-label="Permalink to &quot;Demo Modes: Two Flavors of Awesome&quot;">​</a></h2><p>I built BrandPulse with versatility:</p><ol><li><strong>Fixed Sentiment Mode</strong>: Locked at 35% positive, 30% negative, 35% neutral. The dashboard stays predictable—perfect for testing.</li><li><strong>Volatile Random Mode</strong>: With <code>volatilityFactor</code> at 0.8, sentiment flips like a coin—one batch at 50% neutral, the next at 10%. It’s raw and real.</li></ol><p>Flip the <code>MODE</code> in <code>index.js</code> to switch. Volatile mode proves I can handle the unpredictable.</p><hr><h2 id="why-it-s-a-beast" tabindex="-1">Why It’s a Beast <a class="header-anchor" href="#why-it-s-a-beast" aria-label="Permalink to &quot;Why It’s a Beast&quot;">​</a></h2><ul><li><strong>Speed</strong>: I’ve pushed it to 710k tweets/sec—leagues beyond my early 5k/sec struggles.</li><li><strong>Scale</strong>: 32 Kafka partitions and InfluxDB aggregation eat millions of points for breakfast.</li><li><strong>Real-Time</strong>: Dashboard updates hit every few seconds—fresh data, no delays.</li><li><strong>Adaptability</strong>: Fixed or volatile, it bends to my will.</li></ul><p>Every tweak—from nanosecond timestamps to flush tuning—made this possible (see <code>issues-faced.md</code> for the war stories).</p><hr><h2 id="behind-the-curtain" tabindex="-1">Behind the Curtain <a class="header-anchor" href="#behind-the-curtain" aria-label="Permalink to &quot;Behind the Curtain&quot;">​</a></h2><p>Here’s the engine room:</p><ul><li><strong>Producer.js</strong>: 4 workers, 8k-tweet batches, Avro-serialized, hitting Kafka’s &quot;tweets&quot; topic every 1ms.</li><li><strong>Consumer.js</strong>: Parallel reads, sentiment sums, nanosecond timestamp fixes, and 5k-point InfluxDB flushes.</li><li><strong>Monitor.js</strong>: Real-time stats—throughput peaking at 710k/sec, no errors.</li><li><strong>InfluxDB Query</strong>:<div class="language-flux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">flux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from(bucket: &quot;brandpulse&quot;)</span></span>\n<span class="line"><span>  |&gt; range(start: -1h)</span></span>\n<span class="line"><span>  |&gt; filter(fn: (r) =&gt; r._measurement == &quot;tweets&quot;)</span></span>\n<span class="line"><span>  |&gt; filter(fn: (r) =&gt; r._field == &quot;count&quot;)</span></span>\n<span class="line"><span>  |&gt; aggregateWindow(every: 1s, fn: sum)</span></span>\n<span class="line"><span>  |&gt; group(columns: [&quot;sentiment&quot;])</span></span></code></pre></div>Sums tweets per sentiment per second—efficient and dashboard-ready.</li></ul><hr><h2 id="try-it-out" tabindex="-1">Try It Out <a class="header-anchor" href="#try-it-out" aria-label="Permalink to &quot;Try It Out&quot;">​</a></h2><p>Clone it from <a href="https://github.com/STarLo-rd" target="_blank" rel="noreferrer">my GitHub</a>, follow the README, and run it. Crank the workers, tweak the batch sizes, or dial up the volatility—see how it holds up. I’ve built it tough, but I dare you to break it.</p><hr><h2 id="closing-the-show" tabindex="-1">Closing the Show <a class="header-anchor" href="#closing-the-show" aria-label="Permalink to &quot;Closing the Show&quot;">​</a></h2><p>BrandPulse is my masterpiece—a pipeline that started as a stuttering mess and ended as a roaring machine. This demo is the payoff: raw speed, real-time insights, and a dashboard that tells the story. I’ve got big plans ahead (check <code>future-enhancements.md</code>), but for now, this is BrandPulse at its peak—watch it fly.</p>',57)]))}]]);export{n as __pageData,i as default};
